   const to=style==='slide'?{x:at[0]-9,y:at[1]+6}:style==='book-pull'?{y:at[1]-16}:style==='book-open'?{scaleX:{from:.2,to:1}}:{angle:-55,y:at[1]-6};g.setAlpha(style==='slide'?1:0);this.tweens.add({targets:g,alpha:1,...to,duration:t,ease:'Back.Out'});
