 validPlacement(c:{x:number;y:number}){return walkable(c.x,c.y)&&(this.landOpen||!inLockedLand(c.x,c.y))&&!this.blocked.has(`${c.x},${c.y}`)&&!(this.player.cell.x===c.x&&this.player.cell.y===c.y)&&!this.guests.some(v=>v.actor.cell.x===c.x&&v.actor.cell.y===c.y)}
